      const scope = ui.analysisScope === 'OUTBOUND_ONLY' ? local('只重排 仓库→客户 的归属，不动供应商；数据要求最低。', 'Reassigns site→customer ownership only; suppliers untouched. Lowest data requirements.', '倉庫→顧客の担当のみ変更。') : ui.analysisScope === 'UPSTREAM_ONLY' ? local('保持客户归属，仅重新分配 供应商→仓库 的供货；仓数固定。', 'Keeps customer ownership; reallocates supplier→site supply only; site count fixed.', '顧客担当を固定し、供給元→倉庫の配分のみ再割当。') : local('供应商→仓库→客户 联合决策；确认允许的供货关系和同单位假设。自由模式由求解决定供货量，无需先填每仓答案。', 'Joint supplier→site→customer decisions: confirm allowed links and a common unit. Free mode solves supply amounts; no per-site answer is required.', '供給元→倉庫→顧客を同時決定。許可関係と単位を確認。自由モードでは供給量を求解し、倉庫別の答えを先に入力する必要はありません。');
      const cost = ui.costMode === 'DISTANCE_ONLY' ? local('不计算费用，只比较距离与物量公里。', 'No costs; distance and volume-km only.', '費用は計算しません。') : ui.costMode === 'ASSUMED' ? local('使用手工输入的假设费率（结果会标注为假设）。', 'Uses entered assumed rates (results labeled as assumed).', '仮定料金を使用します。') : local('使用输入的实际费率（需完整，否则不可比）。', 'Uses entered actual rates (must be complete to compare).', '実際料金を使用します。');
      return `<p class="sc-note"><strong>${esc(local('当前选择说明', 'What these mean', '選択の意味'))}</strong><br>${esc(local('研究目标：', 'Objective: ', '目的：'))}${esc(goal)}<br>${esc(local('分析范围：', 'Scope: ', '範囲：'))}${esc(scope)}<br>${esc(local('费用依据：', 'Cost basis: ', '費用：'))}${esc(cost)}</p>`;
