      const rows = model.relations.map(row => `<tr data-map-relation="${esc(encodeURIComponent(row.key))}" data-map-change="${row.change}"><td><span class="sc-change sc-change-${row.change.toLowerCase()}">${esc(words[row.change])}</span></td><td><button type="button" class="sc-rowbtn" data-supply-action="map-locate" data-supply-id="${esc(row.fromNodeId)}">${esc(row.fromName)}</button> → <button type="button" class="sc-rowbtn" data-supply-action="map-locate" data-supply-id="${esc(row.toNodeId)}">${esc(row.toName)}</button>${row.mapped ? '' : `<small>${esc(local('坐标未确认，列表保留', 'Coordinates unconfirmed; retained in list', '座標未確認・一覧に保持'))}</small>`}</td><td>${number(row.before)} → ${number(row.after)} ${esc(study.unit)}</td></tr>`).join('');
      return `${counts}<details class="sc-map-relations" ${model.provenance.nodeId ? 'open' : ''}><summary>${esc(local('核对关系与物量', 'Inspect relations and volumes', '関係と物量を確認'))} · ${model.relations.length}</summary><p class="sc-note">${esc(local('按当前期间、运输段、节点和变化筛选汇总。点击名称可定位；缺坐标的业务记录仍保留。', 'Aggregated for the selected period, leg, node and change filter. Click a name to locate it; records without coordinates are retained.', '選択した期間・区間・拠点・変更で集計。名前で位置を表示し、座標なしの記録も保持します。'))}</p><div class="sc-scroll"><table><thead><tr><th>${esc(local('变化', 'Change', '変更'))}</th><th>${esc(local('来源 → 接收节点', 'Source → receiving node', '供給元 → 受入拠点'))}</th><th>${esc(local('参照 → 候选物量', 'Reference → candidate volume', '参照 → 候補物量'))}</th></tr></thead><tbody>${rows || `<tr><td colspan="3">${esc(local('当前筛选下没有关系；可选择全部关系或其他节点。', 'No relations match. Choose all changes or another node.', '該当する関係はありません。全変更または他の拠点を選択してください。'))}</td></tr>`}</tbody></table></div></details>`;
